fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Since the problem guarantees a.len() == b.len(), we can zip directly.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x % y)
     .collect()
}

